"""Expression evaluation and static validation for minisql.

The evaluator works on the shared AST in :mod:`minisql.ast`.  SQL values are
represented by ``None``, ``bool``, ``int``, ``float`` and ``str``.  Note that
``bool`` is a subclass of ``int`` in Python, so all numeric checks explicitly
exclude booleans.
"""

import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

from .ast import (
    AGGREGATE_NAMES,
    Between,
    Binary,
    Call,
    Column,
    InList,
    IsNull,
    Like,
    Literal,
    Unary,
    children,
    expr_key,
)
from .errors import QueryError


# Function name -> (minimum argument count, maximum argument count or None).
_SCALAR_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISON_OPS = frozenset({"EQ", "NE", "LT", "LE", "GT", "GE"})
_COMPARISON_SYMBOLS = {
    "=": "EQ",
    "==": "EQ",
    "!=": "NE",
    "<>": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


def _is_number(value):
    """Return True for int/float values, excluding bool."""

    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _is_int(value):
    """Return True for integer values, excluding bool."""

    return isinstance(value, int) and not isinstance(value, bool)


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


# ---------------------------------------------------------------------------
# Comparisons and arithmetic
# ---------------------------------------------------------------------------


def compare_values(a, b):
    """Compare two non-NULL SQL values and return -1, 0 or 1.

    Numbers compare numerically, strings by code point and booleans with
    booleans.  Comparing incompatible types raises :class:`QueryError`.
    """

    if a is None or b is None:
        raise QueryError("cannot compare NULL values")

    a_bool = isinstance(a, bool)
    b_bool = isinstance(b, bool)
    if a_bool or b_bool:
        if not (a_bool and b_bool):
            raise QueryError(
                "cannot compare %s with %s"
                % (_type_name(a), _type_name(b))
            )
        return (a > b) - (a < b)

    if _is_number(a) and _is_number(b):
        return (a > b) - (a < b)

    if isinstance(a, str) and isinstance(b, str):
        return (a > b) - (a < b)

    raise QueryError(
        "cannot compare %s with %s" % (_type_name(a), _type_name(b))
    )


def _compare_op(op, left, right):
    if left is None or right is None:
        return None
    cmp = compare_values(left, right)
    if op == "EQ":
        return cmp == 0
    if op == "NE":
        return cmp != 0
    if op == "LT":
        return cmp < 0
    if op == "LE":
        return cmp <= 0
    if op == "GT":
        return cmp > 0
    if op == "GE":
        return cmp >= 0
    raise QueryError("unknown comparison operator: %s" % op)


def _arithmetic(op, left, right):
    if left is None or right is None:
        return None
    if not _is_number(left) or not _is_number(right):
        raise QueryError(
            "arithmetic requires numbers, got %s and %s"
            % (_type_name(left), _type_name(right))
        )

    if op == "/":
        if right == 0:
            return None
        return left / right

    if op == "+":
        result = left + right
    elif op == "-":
        result = left - right
    elif op == "*":
        result = left * right
    else:  # pragma: no cover - guarded by the caller
        raise QueryError("unknown arithmetic operator: %s" % op)

    # Two integers give an integer; otherwise the operation was float and
    # Python already returned a float.
    if _is_int(left) and _is_int(right):
        return int(result)
    return float(result)


def _truth(value):
    """A three-valued logic view of a value: True, False or None."""

    if value is None:
        return None
    return bool(value)


# ---------------------------------------------------------------------------
# LIKE
# ---------------------------------------------------------------------------


def _like_regex(pattern):
    parts = []
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    return "".join(parts)


def _like_match(value, pattern):
    return re.fullmatch(_like_regex(pattern), value, flags=re.DOTALL) is not None


# ---------------------------------------------------------------------------
# Function call shape
# ---------------------------------------------------------------------------


def _check_call_shape(call):
    """Validate a call's name and arity, returning the canonical name."""

    name = call.name.upper()

    if name in AGGREGATE_NAMES:
        if call.star:
            if name != "COUNT":
                raise QueryError(
                    "'*' is only allowed as COUNT(*), not %s(*)" % name
                )
            if call.args:
                raise QueryError("COUNT(*) cannot have arguments")
        elif len(call.args) != 1:
            raise QueryError(
                "%s requires exactly one argument" % name
            )
        return name

    if call.star:
        raise QueryError("'*' is only allowed in COUNT(*)")

    if name not in _SCALAR_ARITY:
        raise QueryError("unknown function: %s" % call.name)

    minimum, maximum = _SCALAR_ARITY[name]
    count = len(call.args)
    if count < minimum or (maximum is not None and count > maximum):
        if minimum == maximum:
            expected = "exactly %d" % minimum
        elif maximum is None:
            expected = "at least %d" % minimum
        else:
            expected = "between %d and %d" % (minimum, maximum)
        raise QueryError(
            "%s requires %s argument(s), got %d" % (name, expected, count)
        )
    return name


# ---------------------------------------------------------------------------
# Column access
# ---------------------------------------------------------------------------


def _column_value(row, name):
    if row is None:
        raise QueryError("column %s used without a row" % name)

    key = name.lower()
    if key in row:
        return row[key]
    for actual, value in row.items():
        if isinstance(actual, str) and actual.lower() == key:
            return value
    raise QueryError("unknown column: %s" % name)


# ---------------------------------------------------------------------------
# Scalar and aggregate evaluation
# ---------------------------------------------------------------------------


def _round_decimal(value, places):
    """Round a number to ``places`` decimal places, halves away from zero."""

    number = Decimal(str(value))
    quantum = Decimal(1).scaleb(-places)
    # Use enough precision for large integer parts; quantize otherwise uses
    # the default 28 digit context and can raise InvalidOperation.
    precision = max(28, len(str(value)) + abs(places) + 5)
    with localcontext() as context:
        context.prec = precision
        return number.quantize(quantum, rounding=ROUND_HALF_UP)


def _eval_scalar(call, name, row, group, inside_aggregate):
    args = call.args

    if name == "COALESCE":
        for arg in args:
            value = _eval(arg, row, group, inside_aggregate)
            if value is not None:
                return value
        return None

    values = [_eval(arg, row, group, inside_aggregate) for arg in args]

    # NULL propagation for all non-COALESCE scalar functions.
    if any(value is None for value in values):
        return None

    if name in ("LOWER", "UPPER", "LENGTH"):
        value = values[0]
        if not isinstance(value, str):
            raise QueryError(
                "%s requires a string, got %s" % (name, _type_name(value))
            )
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if name == "ABS":
        value = values[0]
        if not _is_number(value):
            raise QueryError(
                "ABS requires a number, got %s" % _type_name(value)
            )
        return abs(value)

    if name == "ROUND":
        value = values[0]
        if not _is_number(value):
            raise QueryError(
                "ROUND requires a number, got %s" % _type_name(value)
            )
        if len(values) == 1:
            return int(_round_decimal(value, 0))
        places = values[1]
        if not _is_int(places):
            raise QueryError(
                "ROUND's second argument must be an integer, got %s"
                % _type_name(places)
            )
        return float(_round_decimal(value, places))

    # _check_call_shape guarantees this is unreachable.
    raise QueryError("unknown function: %s" % name)


def _eval_aggregate(call, name, group):
    if call.star:
        return len(group)

    values = []
    for row in group:
        value = _eval(call.args[0], row, None, True)
        if value is not None:
            values.append(value)

    if name == "COUNT":
        return len(values)

    if not values:
        return None

    if name in ("SUM", "AVG"):
        total = 0
        all_int = True
        for value in values:
            if not _is_number(value):
                raise QueryError(
                    "%s requires numbers, got %s"
                    % (name, _type_name(value))
                )
            if isinstance(value, float):
                all_int = False
            total += value
        if name == "SUM":
            return int(total) if all_int else float(total)
        return float(total) / len(values)

    # MIN and MAX use SQL comparison rules.
    best = values[0]
    for value in values[1:]:
        cmp = compare_values(value, best)
        if name == "MIN":
            if cmp < 0:
                best = value
        else:
            if cmp > 0:
                best = value
    return best


# ---------------------------------------------------------------------------
# Main recursive evaluator
# ---------------------------------------------------------------------------


def _eval(expr, row, group, inside_aggregate):
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        return _column_value(row, expr.name)

    if isinstance(expr, Unary):
        op = expr.op.upper()
        value = _eval(expr.operand, row, group, inside_aggregate)
        if op == "NOT":
            if value is None:
                return None
            return not bool(value)
        if op in ("-", "+"):
            if value is None:
                return None
            if not _is_number(value):
                raise QueryError(
                    "unary %s requires a number, got %s"
                    % (op, _type_name(value))
                )
            return -value if op == "-" else value
        raise QueryError("unknown unary operator: %s" % expr.op)

    if isinstance(expr, Binary):
        op = expr.op.upper()

        if op == "AND":
            left = _eval(expr.left, row, group, inside_aggregate)
            if left is not None and not bool(left):
                return False
            right = _eval(expr.right, row, group, inside_aggregate)
            if right is not None and not bool(right):
                return False
            if left is None or right is None:
                return None
            return True

        if op == "OR":
            left = _eval(expr.left, row, group, inside_aggregate)
            if left is not None and bool(left):
                return True
            right = _eval(expr.right, row, group, inside_aggregate)
            if right is not None and bool(right):
                return True
            if left is None or right is None:
                return None
            return False

        left = _eval(expr.left, row, group, inside_aggregate)
        right = _eval(expr.right, row, group, inside_aggregate)

        if op in ("+", "-", "*", "/"):
            return _arithmetic(op, left, right)

        if op == "||":
            if left is None or right is None:
                return None
            return str(left) + str(right)

        comparison = _COMPARISON_SYMBOLS.get(op)
        if comparison is not None:
            return _compare_op(comparison, left, right)

        raise QueryError("unknown binary operator: %s" % expr.op)

    if isinstance(expr, IsNull):
        value = _eval(expr.operand, row, group, inside_aggregate)
        if expr.negated:
            return value is not None
        return value is None

    if isinstance(expr, InList):
        value = _eval(expr.operand, row, group, inside_aggregate)
        saw_null = value is None
        found = False
        for item in expr.items:
            item_value = _eval(item, row, group, inside_aggregate)
            if item_value is None:
                saw_null = True
                continue
            if value is None:
                # NULL = anything is unknown; nothing can match.
                continue
            if _compare_op("EQ", value, item_value):
                found = True
                break
        if found:
            result = True
        elif saw_null:
            result = None
        else:
            result = False
        if expr.negated and result is not None:
            return not result
        return result

    if isinstance(expr, Between):
        value = _eval(expr.operand, row, group, inside_aggregate)
        low = _eval(expr.low, row, group, inside_aggregate)
        lower_ok = _compare_op("LE", low, value)
        if lower_ok is False:
            result = False
        else:
            high = _eval(expr.high, row, group, inside_aggregate)
            upper_ok = _compare_op("LE", value, high)
            if lower_ok is None or upper_ok is None:
                result = None
            else:
                result = bool(lower_ok and upper_ok)
        if expr.negated and result is not None:
            return not result
        return result

    if isinstance(expr, Like):
        value = _eval(expr.operand, row, group, inside_aggregate)
        pattern = _eval(expr.pattern, row, group, inside_aggregate)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError(
                "LIKE requires strings, got %s and %s"
                % (_type_name(value), _type_name(pattern))
            )
        result = _like_match(value, pattern)
        if expr.negated:
            return not result
        return result

    if isinstance(expr, Call):
        name = _check_call_shape(expr)
        if name in AGGREGATE_NAMES:
            if inside_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            if group is None:
                raise QueryError(
                    "aggregate function %s is not allowed here" % name
                )
            return _eval_aggregate(expr, name, group)
        return _eval_scalar(expr, name, row, group, inside_aggregate)

    raise QueryError("unsupported expression: %s" % type(expr).__name__)


def evaluate(expr, row, group=None):
    """Evaluate an :class:`ast.Expr` for one row (or one group).

    ``row`` is a dict mapping lowercase CSV header names to values.  It may be
    ``None`` only when ``group`` is not ``None`` and the expression contains no
    columns (for example ``COUNT(*)`` over the single empty group).

    ``group`` is ``None`` for non-grouped evaluation, otherwise a list of row
    dicts representing the current group.  Aggregate calls are allowed only
    when a group is supplied.
    """

    return _eval(expr, row, group, False)


# ---------------------------------------------------------------------------
# Static validation
# ---------------------------------------------------------------------------


def _validate_expr(expr, headers_lower, allow_aggregate, inside_aggregate):
    if isinstance(expr, Literal):
        return

    if isinstance(expr, Column):
        if expr.name.lower() not in headers_lower:
            raise QueryError("unknown column: %s" % expr.name)
        return

    if isinstance(expr, Call):
        name = _check_call_shape(expr)
        if name in AGGREGATE_NAMES:
            if not allow_aggregate:
                raise QueryError(
                    "aggregate function %s is not allowed here" % name
                )
            if inside_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            for arg in expr.args:
                _validate_expr(arg, headers_lower, allow_aggregate, True)
            return
        for arg in expr.args:
            _validate_expr(arg, headers_lower, allow_aggregate, inside_aggregate)
        return

    for child in children(expr):
        _validate_expr(child, headers_lower, allow_aggregate, inside_aggregate)


def validate_expression(expr, headers, allow_aggregate=True):
    """Statically validate ``expr`` against actual CSV header strings.

    Checks that every column exists (case-insensitively), that every function
    is known and called with the right arity, and that aggregates appear only
    where permitted.  No value types are inferred.
    """

    if expr is None:
        return

    headers_lower = {str(header).lower() for header in headers}
    _validate_expr(expr, headers_lower, bool(allow_aggregate), False)


def _validate_grouped(node, group_keys, inside_aggregate):
    # A complete group-by expression may be used verbatim.
    if not inside_aggregate and expr_key(node) in group_keys:
        return

    if isinstance(node, Call):
        name = _check_call_shape(node)
        if name in AGGREGATE_NAMES:
            if inside_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            for arg in node.args:
                _validate_grouped(arg, group_keys, True)
            return
        for arg in node.args:
            _validate_grouped(arg, group_keys, inside_aggregate)
        return

    if isinstance(node, Column):
        if inside_aggregate:
            return
        raise QueryError(
            "column %s must appear in GROUP BY or be used in an aggregate"
            % node.name
        )

    if isinstance(node, Literal):
        return

    for child in children(node):
        _validate_grouped(child, group_keys, inside_aggregate)


def validate_grouped_expression(expr, group_by_exprs):
    """Validate a non-aggregate expression in a grouped query.

    Columns outside aggregates must be covered by one of the ``GROUP BY``
    expressions.  Nested aggregates are rejected.
    """

    if expr is None:
        return

    group_keys = {expr_key(group_expr) for group_expr in group_by_exprs}
    _validate_grouped(expr, group_keys, False)

